<script>
  const items = [];
  const listEl = document.getElementById('list');
  const countEl = document.getElementById('count');

  function hostOf(u){ try { return new URL(u).hostname.replace(/^www\./,''); } catch(e){ return ''; } }

  function render(){
    countEl.textContent = items.length === 1 ? '1 saved link' : items.length + ' saved links';
    if(items.length === 0){
      listEl.innerHTML = '<div class="empty">No links saved yet. Save your first one above.</div>';
      return;
    }
    listEl.innerHTML = '';
    items.forEach(it => {
      const div = document.createElement('div');
      div.className = 'item';
      const title = it.title || it.url;
      div.innerHTML =
        '<a class="title" href="'+it.url+'" target="_blank" rel="noopener">'+title+'</a>' +
        '<div class="host">'+hostOf(it.url)+'</div>' +
        (it.note ? '<div class="note">'+it.note+'</div>' : '');
